export const GRASS={lush:{label:'Meadow',color:[79,119,59]},mown:{label:'Mown lawn',color:[99,133,66]},dry:{label:'Dry summer',color:[139,142,78]}};
export const BUILDINGS={garage:{label:'Pit garage',width:20,depth:8,height:5},tower:{label:'Control tower',width:8,depth:8,height:14},pavilion:{label:'Pavilion',width:16,depth:10,height:5}};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function buildingSettings(b={}){const type=BUILDINGS[b.type]?b.type:'garage',defaults=BUILDINGS[type],rotation=Number.isFinite(Number(b.rotation))?Number(b.rotation):0;return {type,width:clamp(Number(b.width)||defaults.width,3,60),depth:clamp(Number(b.depth)||defaults.depth,3,40),height:clamp(Number(b.height)||defaults.height,3,30),rotation:((rotation%360)+360)%360,roof:['graphite','terracotta','blue'].includes(b.roof)?b.roof:'graphite'};}
export function buildingCorners(b,scale=.2){const r=b.rotation*Math.PI/180,c=Math.cos(r),s=Math.sin(r);return [[-1,-1],[1,-1],[1,1],[-1,1]].map(([x,y])=>({x:b.x+(x*b.width/2*c-y*b.depth/2*s)/scale,y:b.y+(x*b.width/2*s+y*b.depth/2*c)/scale}));}
export function buildingContains(b,p,scale=.2,padding=0){const r=b.rotation*Math.PI/180,dx=(p.x-b.x)*scale,dy=(p.y-b.y)*scale;return Math.abs(dx*Math.cos(r)+dy*Math.sin(r))<=b.width/2+padding&&Math.abs(-dx*Math.sin(r)+dy*Math.cos(r))<=b.depth/2+padding;}
export function buildingsOverlap(a,b,scale=.2,padding=1){const ac=buildingCorners(a,scale),bc=buildingCorners(b,scale),axes=[a,b].flatMap(v=>{const r=v.rotation*Math.PI/180;return [[Math.cos(r),Math.sin(r)],[-Math.sin(r),Math.cos(r)]];});return axes.every(([x,y])=>{const ap=ac.map(p=>p.x*x+p.y*y),bp=bc.map(p=>p.x*x+p.y*y);return Math.max(...ap)+padding/scale>=Math.min(...bp)&&Math.max(...bp)+padding/scale>=Math.min(...ap);});}
export function drawBuilding(ctx,b,scale=.2,selected=false,zoom=1){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.rotation*Math.PI/180);const w=b.width/scale,d=b.depth/scale;ctx.fillStyle='#203a3540';ctx.fillRect(-w/2+b.height*.25/scale,-d/2+b.height*.18/scale,w,d);ctx.fillStyle='#e2dbc7';ctx.fillRect(-w/2-1,-d/2-1,w+2,d+2);const roof={graphite:'#566267',terracotta:'#a36e52',blue:'#537e91'}[b.roof];ctx.fillStyle=roof;ctx.fillRect(-w/2,-d/2,w,d);ctx.strokeStyle='#ffffff25';ctx.lineWidth=.25/scale;for(let x=-w/2+2/scale;x<w/2;x+=2/scale){ctx.beginPath();ctx.moveTo(x,-d/2);ctx.lineTo(x,d/2);ctx.stroke();}if(b.type==='garage'){const n=Math.max(1,Math.floor(b.width/4));for(let i=0;i<n;i++){ctx.fillStyle='#d9ded7';ctx.fillRect(-w/2+(i+.1)*w/n,d/2-1.1/scale,w/n*.8,1.1/scale);}}else{ctx.fillStyle='#91bbc0';ctx.fillRect(-w*.32,-d*.3,w*.64,d*.6);ctx.strokeStyle='#dbe6de';ctx.strokeRect(-w*.32,-d*.3,w*.64,d*.6);}ctx.strokeStyle=selected?'#f39757':'#283b46';ctx.lineWidth=(selected?2:1)/zoom;ctx.strokeRect(-w/2,-d/2,w,d);if(selected){ctx.strokeStyle='#ffbd7f';ctx.setLineDash([4/zoom,3/zoom]);ctx.strokeRect(-w/2-4/zoom,-d/2-4/zoom,w+8/zoom,d+8/zoom);ctx.setLineDash([]);}ctx.restore();}
const patterns=new WeakMap();
export function grassPattern(ctx,style='mown'){let cache=patterns.get(ctx);if(!cache){cache=new Map();patterns.set(ctx,cache);}if(cache.has(style))return cache.get(style);const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const c=canvas.getContext('2d'),data=c.createImageData(256,256),rgb=grassPixels(style,256);for(let i=0;i<256*256;i++){data.data.set(rgb.subarray(i*3,i*3+3),i*4);data.data[i*4+3]=255;}c.putImageData(data,0,0);const pattern=ctx.createPattern(canvas,'repeat');cache.set(style,pattern);return pattern;}
export function grassPixels(style,size){const base=(GRASS[style]||GRASS.mown).color,pixels=new Uint8Array(size*size*3);let seed=701;for(let y=0;y<size;y++)for(let x=0;x<size;x++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const stripe=style==='mown'?Math.sin(y/size*Math.PI*4)*7:0,grain=((seed>>>16)/65535-.5)*21,blade=Math.sin(x*1.7+y*.8)*3,patch=Math.sin(x/size*6.28)*Math.cos(y/size*6.28)*4;for(let k=0;k<3;k++)pixels[(y*size+x)*3+k]=clamp(Math.round(base[k]+stripe+grain+blade+patch),0,255);}return pixels;}
